153	// ---------------------------------------------------------------------------
154	// Default export — Workers fetch handler
155	// ---------------------------------------------------------------------------
156	
157	export default {
158	  async fetch(request: Request, env: Env, ctx: ExecutionContext): Promise<Response> {
159	    // Boot the Cloudflare implementations on first request (idempotent).
160	    bootCloudflare(env);
161	
162	    // ---------------------------------------------------------------------------
163	    // Per-request service instantiation
164	    // ---------------------------------------------------------------------------
165	    const sidecar = new SidecarClient({
166	      baseUrl: env.SIDECAR_URL,
167	      apiKey: env.SIDECAR_API_KEY,
168	    });
169	    const skillsService = new CfCompanySkillsService(env.PAPERCLIP_STORAGE, sidecar);
170	    const instructionsService = new CfAgentInstructionsService(env.PAPERCLIP_STORAGE);
171	
172	    void skillsService;
173	    void instructionsService;
174	
175	    // Create the DB and storage service for this request.
176	    const db = createHyperdriveDb(env.HYPERDRIVE);
177	    const r2Provider = new R2Provider(env.PAPERCLIP_STORAGE, {
178	      bucket: env.STORAGE_R2_BUCKET ?? "paperclip-storage",
179	      prefix: env.STORAGE_R2_PREFIX ?? "",
180	    });
181	    // Cast to the server's StorageService type — structurally identical at runtime.
182	    const storage = createCfStorageService(r2Provider) as unknown as import(
183	      "../../../server/src/storage/types.js"
184	    ).StorageService;
185	
186	    const deploymentMode = (env.DEPLOYMENT_MODE === "local_trusted"
187	      ? "local_trusted"
188	      : "authenticated") as "local_trusted" | "authenticated";
189	
190	    // Auth resolver called per-route inside mountExpressRouter.
191	    const resolveActor = (req: Request) =>
192	      resolveActorFromRequest(req, db, { deploymentMode });
193	
194	    const mountOptions = { db, storage, resolveActor };
195	
196	    // ---------------------------------------------------------------------------
197	    // Mount route groups
198	    // The "companies" group has the /companies prefix (app.use("/companies", ...))
199	    // in server/src/app.ts; all others are mounted at the root.
200	    // We prepend /api to match how the Express server exposes routes under /api/*.
201	    // ---------------------------------------------------------------------------
202	
203	    // Companies (prefix: /api/companies)
204	    mountExpressRouter(app, companyRoutes(db, storage), "/api/companies", mountOptions);
205	
206	    // Routes registered without a prefix (the router itself contains full paths
207	    // like /companies/:id/agents which already encode /companies/...).
208	    mountExpressRouter(app, agentRoutes(db, {}), "/api", mountOptions);
209	    mountExpressRouter(app, assetRoutes(db, storage), "/api", mountOptions);
210	    mountExpressRouter(app, projectRoutes(db), "/api", mountOptions);
211	    mountExpressRouter(app, issueRoutes(db, storage, {}), "/api", mountOptions);
212	    mountExpressRouter(app, issueTreeControlRoutes(db), "/api", mountOptions);
213	    mountExpressRouter(app, routineRoutes(db, {}), "/api", mountOptions);
214	    mountExpressRouter(app, environmentRoutes(db, {}), "/api", mountOptions);
215	    mountExpressRouter(app, executionWorkspaceRoutes(db), "/api", mountOptions);
216	    mountExpressRouter(app, goalRoutes(db), "/api", mountOptions);
217	    mountExpressRouter(app, approvalRoutes(db, {}), "/api", mountOptions);
218	    mountExpressRouter(app, secretRoutes(db), "/api", mountOptions);
219	    mountExpressRouter(app, costRoutes(db, {}), "/api", mountOptions);
220	    mountExpressRouter(app, activityRoutes(db), "/api", mountOptions);
221	    mountExpressRouter(app, dashboardRoutes(db), "/api", mountOptions);
222	    mountExpressRouter(app, userProfileRoutes(db), "/api", mountOptions);
223	    mountExpressRouter(app, sidebarBadgeRoutes(db), "/api", mountOptions);
224	    mountExpressRouter(app, sidebarPreferenceRoutes(db), "/api", mountOptions);
225	    mountExpressRouter(app, inboxDismissalRoutes(db), "/api", mountOptions);
226	    mountExpressRouter(app, instanceSettingsRoutes(db), "/api", mountOptions);
227	    mountExpressRouter(app, llmRoutes(db), "/api", mountOptions);
228	    mountExpressRouter(app, authRoutes(db), "/api", mountOptions);
229	
230	    // R2-native upload endpoints (replaces multer-based routes).
231	    mountUploadRoutes(app, db);
